# Batch drag: use free slots from drop position, never overwrite unrelated items.
anchor='''    fn move_player_workspace_item(\n        &mut self,\n        source: PlayerItemSelection,'''
batch='''    fn move_player_workspace_items(&mut self, mut sources: Vec<PlayerItemSelection>, target: PlayerItemSelection, cx: &mut Context<Self>) {\n        sources.sort_by_key(|s| (inventory_kind_order(s.kind), s.slot));\n        sources.dedup_by_key(|s| (inventory_kind_order(s.kind), s.slot));\n        if sources.len() <= 1 { if let Some(s)=sources.first().copied(){ self.move_player_workspace_item(s,target,cx); } return; }\n        let Some(id)=self.players.selected.clone() else { return; };\n        if self.players.saving { self.status=SharedString::from("上一项玩家写入尚未完成"); cx.notify(); return; }\n        self.players.saving=true; self.players.generation=self.players.generation.saturating_add(1);\n        let generation=self.players.generation; let world_path=self.world_path.clone(); let count=sources.len();\n        self.status=SharedString::from(format!("正在批量移动 {count} 个物品...")); cx.notify();\n        cx.spawn(async move |handle,cx| {\n            let result=cx.background_spawn(async move {\n                let mut options=bedrock_world::OpenOptions::default(); options.read_only=false;\n                let world=BedrockWorld::open_blocking(&world_path,options).map_err(|e|e.to_string())?;\n                let history=capture_player_history(&world_path,&id,format!("玩家物品：批量拖拽 {count} 项"));\n                let mut data=world.get_player_blocking(&id).map_err(|e|e.to_string())?.ok_or_else(||"玩家记录不存在".to_string())?;\n                let mut items=Vec::new();\n                for source in sources.iter().copied(){ if let Some(item)=player_slot_item(&data.nbt,source){ items.push((source,item)); } }\n                if items.is_empty(){ return Err("已选择物品已经不存在，请刷新玩家数据".to_string()); }\n                for (source,_) in &items { replace_player_slot(&mut data.nbt,*source,None)?; }\n                let capacity=inventory_kind_capacity(target.kind);\n                let mut occupied=player_inventory_entries(&data.nbt).into_iter().filter(|e|e.kind==target.kind)\n                    .map(|e|e.slot.unwrap_or(e.list_index as i32)).collect::<BTreeSet<_>>();\n                let mut candidate=target.slot.clamp(0,capacity.saturating_sub(1)); let mut last=target;\n                for (_,mut item) in items {\n                    let slot=(0..capacity).map(|o|(candidate+o)%capacity).find(|s|!occupied.contains(s))\n                        .ok_or_else(||format!("{}没有足够空槽位",target.kind.label()))?;\n                    occupied.insert(slot); candidate=(slot+1)%capacity;\n                    let dst=PlayerItemSelection{kind:target.kind,list_index:None,slot};\n                    set_workspace_item_slot(&mut item,slot)?; replace_player_slot(&mut data.nbt,dst,Some(item))?; last=dst;\n                }\n                data=PlayerData::from_nbt(id.clone(),data.nbt).map_err(|e|e.to_string())?;\n                world.put_player_blocking(&data).map_err(|e|e.to_string())?; let detail=player_detail_from_data(data)?;\n                if let Ok(capture)=history { complete_after(capture,format!("玩家物品：批量拖拽 {count} 项"))?; }\n                Ok::<_,String>((detail,last))\n            }).await;\n            let Some(view)=handle.upgrade() else { return Ok(()); };\n            view.update(cx,move|this,cx|{\n                if this.players.generation!=generation{return;} this.players.saving=false;\n                match result {\n                    Ok((detail,last))=>{ this.sync_player_summary_inventory_counts(&detail); this.players.detail=Some(detail);\n                        this.player_workspace.multi_selected_items.clear(); this.player_workspace.selected_item=Some(last);\n                        this.player_workspace.item_editor_dirty=false; this.player_workspace.item_editor_error=None;\n                        this.sync_player_item_raw_editor(cx); this.status=SharedString::from("批量物品移动完成 · 未覆盖其他槽位 · 可从历史撤销"); },\n                    Err(error)=>{this.player_workspace.item_editor_error=Some(SharedString::from(error.clone()));this.status=SharedString::from(error);}\n                } cx.notify();\n            })?; Ok::<(),anyhow::Error>(())\n        }).detach();\n    }\n\n'''
w=rep(w,anchor,batch+anchor,W)
helper='''fn workspace_tab_button(colors: &ThemeColors, label: &'static str, active: bool) -> Div {'''
w=rep(w,helper,'''fn inventory_kind_order(kind: PlayerInventoryKind) -> u8 { match kind { PlayerInventoryKind::Inventory=>0, PlayerInventoryKind::Armor=>1, PlayerInventoryKind::Offhand=>2, PlayerInventoryKind::EnderChest=>3 } }\nfn inventory_kind_capacity(kind: PlayerInventoryKind) -> i32 { match kind { PlayerInventoryKind::Inventory=>36, PlayerInventoryKind::Armor=>4, PlayerInventoryKind::Offhand=>1, PlayerInventoryKind::EnderChest=>27 } }\n\n'''+helper,W)
