# Resource packs: exact vanilla/chemistry first, then versioned families. Items first, 2D blocks fallback.
m=re.search(r'fn load_item_catalog\(instance_root: &Path\) -> Vec<PlayerItemTexture> \{.*?\n\}\n\nfn texture_reference',p,re.S)
if not m: raise SystemExit('load_item_catalog block missing')
loader='''fn player_resource_pack_roots(instance_root: &Path) -> Vec<PathBuf> {\n    let root=instance_root.join("data").join("resource_packs"); let mut out=Vec::new();\n    for name in ["vanilla","chemistry"] { let p=root.join(name); if p.is_dir(){out.push(p);} }\n    let mut versioned=Vec::<(String,PathBuf)>::new();\n    if let Ok(entries)=fs::read_dir(&root){ for e in entries.flatten(){ let p=e.path(); if !p.is_dir(){continue;}\n        let Some(name)=p.file_name().and_then(|v|v.to_str()) else {continue};\n        if name.starts_with("vanilla_")||name.starts_with("chemistry_"){versioned.push((name.to_ascii_lowercase(),p));}\n    }}\n    versioned.sort_by(|a,b| { let af=if a.0.starts_with("vanilla_"){0}else{1}; let bf=if b.0.starts_with("vanilla_"){0}else{1}; af.cmp(&bf).then_with(||b.0.cmp(&a.0)) });\n    out.extend(versioned.into_iter().map(|(_,p)|p)); out\n}\nfn add_texture(by_id:&mut BTreeMap<String,PlayerItemTexture>,pack:&Path,key:&str,texture:&str){\n    let path=pack.join(format!("{texture}.png")); if !path.is_file(){return;} let id=normalize_item_id(key);\n    by_id.entry(id.clone()).or_insert_with(||PlayerItemTexture{id:SharedString::from(id),label:SharedString::from(key.replace('_'," ")),path:Arc::<Path>::from(path.into_boxed_path())});\n}\nfn scan_flat_textures(by_id:&mut BTreeMap<String,PlayerItemTexture>,dir:&Path){\n    let Ok(entries)=fs::read_dir(dir) else{return;}; for e in entries.flatten(){let path=e.path();\n        if !path.extension().and_then(|v|v.to_str()).is_some_and(|v|v.eq_ignore_ascii_case("png")){continue;}\n        let Some(stem)=path.file_stem().and_then(|v|v.to_str()) else{continue}; if stem.ends_with("_0")||stem.ends_with("_1"){continue;}\n        let id=normalize_item_id(stem); by_id.entry(id.clone()).or_insert_with(||PlayerItemTexture{id:SharedString::from(id),label:SharedString::from(stem.replace('_'," ")),path:Arc::<Path>::from(path.into_boxed_path())});\n    }\n}\nfn load_item_catalog(instance_root: &Path) -> Vec<PlayerItemTexture> {\n    let mut by_id=BTreeMap::<String,PlayerItemTexture>::new();\n    for pack in player_resource_pack_roots(instance_root){ let textures=pack.join("textures");\n        for atlas in ["item_texture.json","terrain_texture.json"] { let file=textures.join(atlas);\n            if let Ok(bytes)=fs::read(file) && let Ok(value)=serde_json::from_slice::<serde_json::Value>(&bytes)\n                && let Some(data)=value.get("texture_data").and_then(|v|v.as_object()){\n                for (key,entry) in data { if let Some(texture)=texture_reference(entry){add_texture(&mut by_id,&pack,key,texture);} }\n            }\n        }\n        scan_flat_textures(&mut by_id,&textures.join("items"));\n        scan_flat_textures(&mut by_id,&textures.join("blocks"));\n    }\n    by_id.into_values().collect()\n}\n\nfn texture_reference'''
p=p[:m.start()]+loader+p[m.end():]; wr(P,p)
